async function api(path,body={}){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),12000);try{const r=await fetch('/api/'+path,{method:'POST',headers:{'Content-Type':'application/json','X-Telegram-Init-Data':tg.initData},body:JSON.stringify({...body,timezone:Intl.DateTimeFormat().resolvedOptions().timeZone||'Europe/Kyiv'}),signal:controller.signal});let data;try{data=await r.json();}catch{throw new Error('Сервер не відповів коректно. Спробуй ще раз.');}if(!r.ok)throw new Error(data.error||'Не вдалося зберегти. Спробуй ще.');if(data.reminders)remindersEnabled=data.reminders.enabled;return data;}catch(e){if(e.name==='AbortError')throw new Error('Сервер довго відповідає. Натисни ОК ще раз.');throw e;}finally{clearTimeout(timer);}}
function pixel(ctx,x,y,w,h,c){ctx.fillStyle=c;ctx.fillRect(Math.round(x),Math.round(y),w,h);}
function drawBase(canvas,id,frame=0,s=null,preview=false,spriteOnly=false){if(detailedReady()){drawDetailedPortrait(canvas,id,s,frame,preview,effect,reduced);return;}const c=canvas.getContext('2d');c.clearRect(0,0,128,100);if(s&&!preview&&!spriteOnly)drawHome(c,s,frame);const ink='#35482e',light='#e8ecc3';const spec=species.find(p=>p.id===id)||species[1];const age=s?(s.portraitStage||stage(s)):'Дорослий';
 let y=(preview||reduced||s?.vacation?0:Math.sin(frame/270)*2)-Math.max(0,bounce);c.save();const pose=spriteOnly?{...behaviorPose(s,age,frame,reduced),x:0}:poseFor(s,age,frame,preview);c.translate(pose.x,Math.round(y)+pose.y);
 const r=(x,y,w,h,col=ink)=>pixel(c,x,y,w,h,col);const box=(x,y,w,h,col)=>{r(x-2,y, w+4,h);r(x,y-2,w,h+4);r(x,y,w,h,col);};
 if(s?.dead){r(46,51,36,27);r(51,43,26,12);r(61,49,5,20,light);r(55,55,17,5,light);c.restore();return;}
 if(s&&age==='Яєчко'&&!preview){
 const index=species.findIndex(p=>p.id===id),wobble=reduced||s.sleeping?0:Math.floor(frame/220)%3-1;c.translate(wobble,0);
 box(52,43,24,31,light);r(56,37,16,8,ink);r(57,39,14,7,light);r(49,53,3,15,ink);r(76,53,3,15,ink);
 r(55,51,5,5,spec.color);r(66,59,6,5,spec.color);r(56,67,4,4,spec.color);r(65+(index%3)*2,46,3,3,ink);r(57+(index%4)*3,61,3,3,spec.color);
 if((Date.now()-s.born)>life.egg-60000){r(62,48,3,7);r(59,55,3,4);r(62,59,3,5);r(65,64,3,5);}c.restore();return;}
 if(!preview&&(age==='Малюк'||age==='Дитина'||age==='Підліток')){drawYoungPet(c,id,age,spec.color,frame,s?.sleeping,reduced);c.restore();return;}
 drawPetArt(c,id,frame,s,reduced||preview);
 c.restore();
}
