function poseFor(s,age,frame,preview=false){if(!s||preview)return {x:0,y:0,kind:'rest'};const p=behaviorPose(s,age,frame,reduced);if(!reduced&&!s.sleeping&&!s.napping&&['Підліток','Дорослий','Старенький'].includes(age)){if(careForm(s)==='cozy'){p.x=Math.round(p.x*.5);p.y+=2;}if(careForm(s)==='scruffy'&&p.kind==='walk')p.y-=Math.floor(frame/210)%2*2;if(effectActive()&&['trick','walk'].includes(effect.kind))p.y-=Math.floor(frame/220)%2*5;}if(s.room?.bed&&(s.sleeping||s.napping)&&age!=='Яєчко')p.x=furniturePositions(s).bed+24-64;else if(s.room?.bowl&&effectActive()&&effect.kind==='feed'&&!s.portraitStage)p.x=furniturePositions(s).bowl+12-64;if(p.kind==='sit'&&!(s.world?.walk?.expires>Date.now()))p.x=favoriteCorner(s).x;if(s.playroom?.session?.expires>Date.now()&&!s.sleeping&&!s.napping){const run=s.playroom.session;p.x=20+run.pet*10-64;p.y=run.kind==='music'&&!reduced?-Math.floor(frame/180)%2*5:run.kind==='laser'&&(s.playroom.skills.laser||0)>=3?3:0;}return p;}
function effectActive(){return effect&&Date.now()<effect.until;}
function render(){const s=state,has=!!s;$('#sandbox-controls').hidden=mode!=='sandbox';$('#adoption').hidden=has;$('#care').hidden=!has;$('#connection').textContent=online?'TG • SYNC':'DEMO • LOCAL';$('#confirm-panel').hidden=mode!=='confirm';$('#mini-game').hidden=mode!=='game';$('#pet-touch').hidden=mode==='confirm'||mode==='game'||panelModes.includes(mode);$('#choice-panel').hidden=!panelModes.includes(mode);$('#rules').hidden=mode!=='rules';$('#save-info').textContent=online?'Прогрес прив’язаний до твого Telegram.':'Деморежим: прогрес зберігається в цьому браузері.';
 $('#pet-name').textContent=s?s.name:species.find(p=>p.id===selected).name;$('#age').textContent=s?'DAY '+String(Math.floor(((s.vacation?.started??Date.now())-s.born)/86400000)+1).padStart(2,'0'):'♡';$('#stage').textContent=s?(s.dead?'НА ВЕСЕЛЦІ ♡':s.vacation?'ВІДПУСТКА · ПАУЗА':(s.sleeping||s.napping)?'ТИХО, ВІН СПИТЬ':(stage(s)==='Яєчко'?'ЯЙЦЕ · '+Math.max(0,Math.ceil((s.born+life.egg-Date.now())/60000))+' ХВ':stage(s).toUpperCase())):'← → ОБРАТИ · ОК ЗАБРАТИ';$('#coins').textContent='✦ '+(s?.coins??20);
 $('#menu-icons').setAttribute('data-level',menuGroup?'category':'root');$('#menu-icons').replaceChildren();for(let i=0;i<menu.length;i++){const el=document.createElement('span');el.replaceChildren(actionIcon(menu[i][0]));el.className=has&&i===picked?'active':'';el.setAttribute('aria-label',menu[i][2]);if(has&&i===picked)el.setAttribute('aria-current','true');if(menu[i][0]==='adventure'&&s?.adventure)el.className+=' pending';$('#menu-icons').append(el);}
 document.querySelectorAll('.species-card').forEach((el,i)=>{el.classList.toggle('selected',species[i].id===selected);});
 $('#confirm-title').textContent=confirmKind==='family'?'Нове покоління?':confirmKind==='vacation'?'Відправити у відпустку?':'Завершити життя пета?';$('#confirm-description').textContent=confirmKind==='vacation'?'Потреби, старіння та нагадування призупиняться. Повернеш друга через це саме меню.':confirmKind==='family'?'Батьки залишаться в альбомі. На екрані з’явиться нове яйце цього виду; вік і потреби почнуться спочатку.':'Пет помре. Його історія залишиться в альбомі. Потім можна обрати нового друга.';$('#confirm-choice').textContent=confirmYes?(confirmKind==='family'?'ТАК, НОВЕ ЯЙЦЕ':confirmKind==='vacation'?'ТАК, У ГОТЕЛЬ':'ТАК, ЗАВЕРШИТИ ЖИТТЯ'):'НІ, ЗАЛИШИТИ';
 $('#selected-action').textContent=busy||loading?'ЗАЧЕКАЙ, У МЕНЕ ЛАПКИ…':mode==='confirm'?'← → ВИБІР · ОК ПІДТВЕРДИТИ':mode==='game'?'← → РУХ · ОК ЛОВИТИ · ↶ ВИХІД':panelModes.includes(mode)?'← → ВИБІР · ОК · ↶ НАЗАД':mode==='rules'?'↶ ПОВЕРНУТИСЯ':!s?'← → '+species.find(p=>p.id===selected).name.toUpperCase()+' · ОК ЗАБРАТИ':s.dead?(deadChoice?'ОК — АЛЬБОМ ПОКОЛІНЬ':'ОК — ОБРАТИ НОВОГО ДРУГА'):(menu[picked][0]==='vacation'&&s?.vacation?'ПОВЕРНУТИСЯ З ВІДПУСТКИ':menu[picked][2].toUpperCase())+(menu[picked][0]==='sound'?(audio.enabled?' · УВІМК.':' · ВИМК.'):menu[picked][0]==='reminders'?(remindersEnabled?' · УВІМК.':' · ВИМК.'):'');
 for(const id of ['left','right','ok'])$('#button-'+id).disabled=busy||loading;
 if(panelModes.includes(mode))renderChoice();$('#stats').replaceChildren();if(!s)return;$('#level').textContent='LVL '+(Math.floor(s.xp/30)+1);for(const [key,label] of [['hunger','Ситість'],['happy','Настрій'],['energy','Енергія'],['clean','Чистота'],['health','Здоров’я'],['discipline','Виховання'],['bond','Прив’язаність'],...(s.social?[[ 'mental','Спокій']]:[])]){const div=document.createElement('div');div.innerHTML=`<div class="stat-label"><span>${label}</span><span>${Math.round((key==='mental'?s.social?.mental:s[key])??70)}%</span></div><div class="bar"><i class="${((key==='mental'?s.social?.mental:s[key])??70)<25?'low':''}" style="width:${(key==='mental'?s.social?.mental:s[key])??70}%"></i></div>`;$('#stats').append(div);}}
async function action(a,details={}){if(busy||!state)return;busy=true;generation++;$('#error').hidden=true;render();try{const result=online?await api('action',{action:a,game:details.game,food:details.food}):act(state,a,Date.now(),details);if(result.state)state=result.state;if(!online)save();speak(result.error||result.text||'');if(!result.error){bounce=5;effect={kind:a,food:details.food||(a==='feed'?foodsFor(state,stage(state))[0]:null),started:Date.now(),until:Date.now()+(a==='pet'?2400:1800)};void audio.react(a==='sleep'?(state.sleeping?'sleep':'wake'):(a==='feed'||a==='treat')&&(effect.food||foodFor(state.species,stage(state),a))==='milk'?'milk':a,state.species);try{tg?.HapticFeedback?.impactOccurred('light');}catch{}}}catch(e){fail(e.message);}finally{busy=false;render();}}
for(const s of species){const card=document.createElement('div');card.className='species-card';const cv=document.createElement('canvas');cv.width=128;cv.height=100;cv.setAttribute('aria-hidden','true');const label=document.createElement('span');label.textContent=s.name;card.append(cv,label);draw(cv,s.id,0,null,true);$('#species').append(card);}
async function adopt(){if(busy||loading)return;busy=true;generation++;$('#error').hidden=true;render();try{const name=$('#nickname').value.trim();if(online){const r=await api('adopt',{species:selected,name});state=r.state;speak(r.text);}else{state=fresh(selected);if(name)state.name=name;save();speak('У яйці хтось ворушиться. Годинник налаштовано, чекаємо 3 хвилини.');}choosingNew=false;rootMenu();picked=0;void audio.react('adopt',state.species);}catch(e){fail(e.message);}finally{busy=false;render();}}
function newFriend(){rootMenu();choosingNew=true;generation++;deadChoice=0;if(state?.dead&&!online)rememberLocal(state,state.endReason||'death');state=null;mode='normal';picked=0;if(!online)save();speak('Обирай нового друга. Для обіймів завжди є місце.');render();}
function move(direction){if(busy||loading)return;if(mode==='sandbox'){choice=(choice+direction+Math.max(1,sandboxPets.length*4))%Math.max(1,sandboxPets.length*4);render();return;}if(cozyPages.some(([id])=>id===mode)){const count=cozyCount();choice=(choice+direction+count)%count;render();return;}if(playroomPages.some(([id])=>id===mode)){if(mode==='toys'&&state.playroom?.session?.expires>Date.now()){void toyInput(direction<0?'left':'right');return;}const count=mode==='toys'?toys.length:mode==='craft'?recipes.length:decorFields.length;choice=(choice+direction+count)%count;render();return;}if(dailyPages.some(([id])=>id===mode)){const count=dailyCount();choice=(choice+direction+count)%count;render();return;}if(worldModes.includes(mode)){const count=mode==='world'?worldPages.length:mode==='ritual'?3:mode==='walk'?(state.world?.walk?.expires>Date.now()?2:walks.length):mode==='activity'?(state.world?.activity?.expires>Date.now()?1:activities.length):1;choice=(choice+direction+count)%count;render();return;}if(mode==='confirm'){confirmYes=!confirmYes;render();return;}if(mode==='game'){gameMove(game,direction);renderGame();return;}if(mode==='games'){choice=(choice+direction+gameTypes.length)%gameTypes.length;render();return;}if(mode==='family'){choice=(choice+direction+3)%3;render();return;}if(mode==='album'){void moveAlbum(direction);return;}if(['food','room','routine','adventure','tree'].includes(mode)){const length=mode==='food'?foodsFor(state,stage(state)).length:mode==='room'?furnishings.length:mode==='routine'?routineFields.length:mode==='tree'?treeRecords.length:adventureOf(state)?.choices.length||1;if(mode==='tree')treeIndex=(treeIndex+direction+Math.max(1,length))%Math.max(1,length);else choice=(choice+direction+length)%length;render();return;}if(mode==='memory'||mode==='rules')return;if(!state){const i=species.findIndex(s=>s.id===selected);selected=species[(i+direction+species.length)%species.length].id;speak(species.find(s=>s.id===selected).nick+': «Забирай. Я хороший. Майже.»');}else if(state.dead){deadChoice=1-deadChoice;}else{picked=(picked+direction+menu.length)%menu.length;}render();}
async function ok(){if(busy||loading)return;if(worldModes.includes(mode)){await worldOK();return;}if(mode==='confirm'){if(!confirmYes){mode='normal';speak('От і добре. Іди сюди, обійму.');render();return;}mode='normal';if(confirmKind==='family')await createFamily();else if(confirmKind==='vacation')await companion('vacationStart');else await action('endLife');return;}if(mode==='food'){const food=foodsFor(state,stage(state))[choice];mode='normal';await action('feed',{food});return;}if(mode==='room'){const item=furnishings[choice];if(state.room?.[item.id]){mode='belongings';choice=Math.max(0,ownedThings(state).findIndex(i=>i.id===item.id))*4;render();}else await useRoom();return;}if(mode==='routine'){const field=routineFields[choice][0];await companion(field==='enabled'?'routineToggle':'routineHour',{field},true);return;}if(mode==='memory'){mode='normal';render();return;}if(mode==='tree'){if(treeRecords.length)treeIndex=(treeIndex+1)%treeRecords.length;render();return;}if(mode==='adventure'){if(!state.adventure){mode='normal';render();return;}await companion('adventure',{eventId:state.adventure.id,choice});return;}if(mode==='games'){startGame(gameTypes[choice].id);return;}if(mode==='album'){await moveAlbum(1);return;}if(mode==='family'){confirmKind='family';confirmYes=false;mode='confirm';render();return;}if(mode==='game'){catchBug();return;}if(mode==='rules'){mode='normal';render();return;}if(!state){await adopt();return;}if(state.dead){if(deadChoice)await openAlbum();else newFriend();return;}const a=menu[picked][0];if(a.startsWith('group:')){groupMenu(a.slice(6));render();return;}if(a==='sandbox'){mode='sandbox';choice=0;render();await sandboxAction('join');return;}if(a==='stories'){mode='stories';choice=0;render();return;}if(worldPages.some(([id])=>id===a)){mode=a;choice=0;render();if(a==='photos')await openMoments();return;}if(a==='pet'&&state.cozy?.peace?.tension>0){mode='peace';choice=0;render();return;}if(a==='world'){choice=0;mode='world';render();return;}if(a==='endLife'){confirmKind='endLife';mode='confirm';confirmYes=false;render();return;}if(a==='sound'){audio.enabled=!audio.enabled;try{localStorage.setItem('hamagochi-sound',audio.enabled?'on':'off');}catch{}if(audio.enabled){const played=await beep();if(!played)speak('Звук недоступний. Перевір гучність пристрою.');else speak('Пік! Тепер я ще й пищу.');}else speak('Тихенько бурчатиму без звуку.');render();return;}if(a==='feed'){if(state.vacation||stage(state)==='Яєчко'||state.sleeping||state.napping){await action('feed');return;}choice=0;mode='food';render();return;}if(a==='memory'){mode='memory';render();return;}if(a==='room'||a==='routine'||a==='adventure'){choice=0;mode=a;render();return;}if(a==='tree'){await openTree();return;}if(a==='vacation'){if(state.vacation){await companion('vacationResume');return;}confirmKind='vacation';confirmYes=false;mode='confirm';render();return;}if(a==='reminders'){await toggleReminders();return;}if(a==='album'){await openAlbum();return;}if(a==='family'){const error=familyEligibility(state);if(error){speak(error);return;}choice=0;mode='family';render();return;}if(a==='rules'){mode='rules';render();return;}if(a==='status'){speak(species.find(s=>s.id===state.species).name+' '+state.name+'. '+stage(state)+' · '+temperament(state)+'. '+traits[traitOf(state)].name+' · покоління '+(state.generation||1)+'. '+formNames[careForm(state)]+'. Виховання: '+Math.round(state.discipline??70)+'%.');return;}if(a==='play'){if(state.vacation||state.sleeping||state.napping||stage(state)==='Яєчко'||state.energy<12){await action(a);return;}choice=0;mode='games';render();return;}await action(a);}
function back(){if(busy)return;if(mode==='sandbox'){clearInterval(sandboxTimer);sandboxTimer=null;if(online)void api('sandbox',{command:'leave'}).catch(()=>{});mode='normal';render();return;}if(mode==='normal'&&menuGroup){rootMenu();render();return;}if(mode==='toys'&&state.playroom?.session){void playroomAction('toyCancel');mode='normal';choice=0;render();return;}if(worldModes.includes(mode)&&mode!=='world'){mode='normal';choice=0;render();return;}if(mode==='game'){endGame(false,true);return;}if(mode!=='normal'){mode='normal';confirmYes=false;render();return;}if(!state){void openAlbum();return;}picked=0;speak(state?'Я тут. Просто посидимо поруч?':'Обирай кнопками ← →, а потім натисни ОК.');render();}
for(const [id,handler] of [['left',()=>move(-1)],['right',()=>move(1)],['ok',ok],['back',back]]){$('#button-'+id).addEventListener('pointerdown',()=>{void audio.unlock();});$('#button-'+id).onclick=()=>{void audio.unlock();if(!(state&&mode==='normal'&&menu[picked][0]==='sound'&&id==='ok'))void beep();handler();};}
function renderGame(){if(!game)return;const v=gameView(game),type=gameTypes.find(t=>t.id===game.kind);if(detailedReady())drawDetailedMiniGame($('#game-canvas'),game,state);else drawGame($('#game-canvas').getContext('2d'),game);$('#game-title').textContent=type.name;$('#game-scene').textContent=v.scene;$('#game-cursor').textContent=v.cursor;$('#game-hint').textContent=v.hint;$('#game-count').textContent=game.hits+'/5 · помилки '+game.misses+'/3 · '+Math.max(0,Math.ceil((game.until-Date.now())/1000))+' с';}
function startGame(kind='bug'){mode='game';game=makeGame(kind);game.timer=setInterval(()=>{advanceGame(game);if(game.done)endGame(game.won);else renderGame();},100);render();renderGame();}
function catchBug(){if(!game)return;const r=pressGame(game);if(!r.ignored){if(r.hit)beep(950);else void audio.react('miss',state.species);}if(game.done)endGame(game.won);else renderGame();}
function endGame(won,cancel=false){if(!game)return;const kind=game.kind;clearInterval(game.timer);game=null;mode='normal';render();if(won)void action('play',{game:kind});else speak(cancel?'Перепочинемо. Гра зачекає.':'Не вийшло. Я все одно люблю з тобою грати. Ще раз?');}
function renderChoice(){renderInteractionControls();const icon=$('#choice-action-icon'),iconKey=mode==='belongings'?objectActions(ownedThings(state)[Math.floor(choice/4)]?.id)[choice%4][0]:mode==='food'?'feed':mode;paintIcon(icon.getContext('2d'),iconKey,2);const portrait=$('#choice-portrait');portrait.width=128;portrait.height=100;if(worldModes.includes(mode)){renderWorldChoice(portrait);return;}if(['food','memory','room','routine','adventure','tree'].includes(mode)){renderCompanionChoice(portrait);return;}portrait.hidden=mode==='games';if(mode==='games'){$('#choice-title').textContent=(choice+1)+'/4 · '+gameTypes[choice].name;$('#choice-detail').textContent=gameTypes[choice].hint+'\n5 успіхів · до 3 помилок · +3 монети';return;}if(mode==='family'){const partner=candidates(state)[choice];$('#choice-title').textContent=partner.name+' · '+traits[partner.trait].name;$('#choice-detail').textContent=(choice+1)+'/3 · '+species.find(p=>p.id===partner.species).name+'\nОК — обрати пару й підтвердити нове яйце';draw(portrait,partner.species,0,{...state,name:partner.name,portraitStage:'Дорослий',appearance:partner.appearance,trait:partner.trait,sleeping:false,napping:false,poop:0},false);return;}const row=albumRecords[albumIndex];portrait.hidden=!row;if(!row){$('#choice-title').textContent='Альбом ще порожній';$('#choice-detail').textContent='Тут залишаться портрети й історії попередніх друзів. ↶ — повернутися';return;}$('#choice-title').textContent=row.name+' · покоління '+row.generation;const duration=row.ageMs/86400000;$('#choice-detail').textContent=(albumIndex+1)+' · '+(row.outcome==='family'?'Нове покоління ♥':'На веселці ♡')+'\n'+row.stage+' · '+(duration<1?Math.floor(row.ageMs/60000)+' хв':duration.toFixed(1)+' діб')+'\n'+row.character+' · '+(traits[row.trait]?.name||'Буркотун')+(row.partner?'\nПара: '+row.partner.name:'');draw(portrait,row.species,0,portraitState(row),false);}
async function openAlbum(){if(busy)return;mode='album';albumIndex=0;busy=true;render();try{if(online){const r=await api('album');albumRecords=r.records;albumCursor=r.cursor;albumMore=r.hasMore;}else{if(state?.dead)rememberLocal(state,state.endReason||'death');albumRecords=localAlbum();albumMore=false;}}catch(e){fail(e.message);}finally{busy=false;render();}}
async function moveAlbum(direction){if(busy)return;if(direction>0&&albumIndex===albumRecords.length-1&&albumMore&&online){busy=true;render();try{const r=await api('album',{cursor:albumCursor});albumRecords.push(...r.records);albumCursor=r.cursor;albumMore=r.hasMore;}catch(e){fail(e.message);}finally{busy=false;}}if(albumRecords.length)albumIndex=Math.max(0,Math.min(albumRecords.length-1,albumIndex+direction));render();}
async function createFamily(){if(busy)return;busy=true;generation++;render();try{const partner=candidates(state)[choice],parentBefore={...state,portraitStage:'Дорослий',sleeping:false,napping:false,poop:0};const result=online?await api('family',{partnerId:partner.id}):nextGeneration(state,partner.id);if(result.error)throw Error(result.error);if(!online)rememberLocal(state,'family',result.record);const parentCanvas=document.createElement('canvas'),partnerCanvas=document.createElement('canvas');for(const c of [parentCanvas,partnerCanvas]){c.width=128;c.height=100;}drawBase(parentCanvas,parentBefore.species,0,parentBefore,true);drawBase(partnerCanvas,partner.species,0,{...parentBefore,trait:partner.trait},true);familyScene={parent:parentCanvas,partner:partnerCanvas,until:Date.now()+3000};state=result.state;effect=null;if(!online)save();picked=0;speak(result.text);void audio.react('adopt',state.species);}catch(e){fail(e.message);}finally{busy=false;mode='normal';render();}}
async function load(){if(loading||busy||choosingNew)return;loading=true;const revision=generation;render();let greeting=null;try{if(online){const r=await api('state');greeting=r.greeting;if(revision===generation)state=r.state;}else{try{const raw=JSON.parse(localStorage.getItem('hamagochi-v1'));if(raw&&species.some(s=>s.id===raw.species)&&['born','updated','hunger','happy','energy','clean','health','coins','xp'].every(k=>Number.isFinite(raw[k])))state=tick(raw);}catch{}}if(state&&!online){greeting=visit(state);save();}if(state)speak(state.dead?'На веселці тепло. ОК — обрати нового друга.':state.sleeping?'Тихенько. Я ще дрімаю.':greeting||'О, моя людина! '+traits[traitOf(state)].line);}catch(e){fail(e.message);}finally{loading=false;render();}}
let previous=0;function animate(t){if(t-previous>80){draw($('#pet'),state?.species||selected,t,state);if(state&&mode==='sandbox')drawSandbox($('#choice-portrait'));if(state&&worldModes.includes(mode)&&!['world','photos','sandbox'].includes(mode)){if(mode==='hide'&&state.cozy?.hide?.expires>Date.now()&&detailedReady()){drawDetailedMain($('#choice-portrait'),state,state.species,t,reduced,null,effect);}else if(mode==='hide'&&state.cozy?.hide?.expires>Date.now()){const cv=$('#choice-portrait');cv.width=192;cv.height=144;drawExpandedRoom(cv.getContext('2d'),state,t,reduced);drawHideClue(cv.getContext('2d'),state);}else draw($('#choice-portrait'),state.species,t,state);}bounce*=.65;previous=t;}requestAnimationFrame(animate);}requestAnimationFrame(animate);
setInterval(async()=>{if(!state||busy||loading||mode!=='normal'||document.hidden)return;const revision=generation;if(online){try{const r=await api('state');if(revision!==generation||busy||mode!=='normal'||choosingNew)return;state=r.state;if(r.greeting)speak(r.greeting);}catch{return;}}else{state=tick(state);save();}render();if(state&&!state.dead&&Date.now()-lastSpeech>25000)speak(idleSpeech(state));},15000);
document.addEventListener('visibilitychange',()=>{if(document.hidden){void audio.suspend();if(game)endGame(false,true);}else if(!busy&&mode==='normal')void load();});render();void load();

let displayedStage=state?stage(state):null,displayedBorn=state?.born;
setInterval(()=>{if(!state||state.dead)return;const removed=state.cozy?.lastRemoved?.at;updateCozy(state);if(state.cozy?.lastRemoved?.at!==removed){if(!online)save();speak('Зняв незручний одяг. Давай приміряємо щось інше, людино?');if(mode==='wardrobe'&&!busy)render();}const current=stage(state);if(displayedBorn===state.born&&displayedStage&&displayedStage!==current){speak(current==='Малюк'?'Трісь! Я вилупився. Де моя людина й обійми?':current==='Дитина'?'Я виспався й підріс. Дивися, які лапки!':current==='Підліток'?'Я вже підліток. Характер росте швидше за лапки.':current==='Старенький'?'Я вже старенький. Посидь зі мною, моя людино.':'Я дорослий! Але на ручки все одно хочу.');void audio.react('adopt',state.species);}displayedStage=current;displayedBorn=state.born;if(mode==='normal'&&!busy)render();},1000);

async function toggleReminders(){
 if(!online){speak('Нагадування доступні в Telegram. Відкрий гру з бота.');return;}
 if(busy)return;
 busy=true;render();try{
 if(!remindersEnabled){
 if(typeof tg.requestWriteAccess!=='function')throw new Error('Онови Telegram, щоб дозволити повідомлення від пета.');
 const allowed=await new Promise(resolve=>{const timeout=setTimeout(()=>resolve(false),60000);tg.requestWriteAccess(ok=>{clearTimeout(timeout);resolve(ok);});});
 if(!allowed){speak('Без дозволу не писатиму. Увімкнути можна пізніше.');return;}
 }
 const timezone=Intl.DateTimeFormat().resolvedOptions().timeZone||'Europe/Kyiv';
 const r=await api('reminders',{enabled:!remindersEnabled,timezone});speak(r.text);$('#error').hidden=true;
 }catch(e){fail(e.message);}finally{busy=false;render();}
}

function renderCompanionChoice(portrait){portrait.hidden=true;const title=$('#choice-title'),detail=$('#choice-detail');
 if(mode==='food'){const list=foodsFor(state,stage(state)),food=list[choice];title.textContent=(choice+1)+'/'+list.length+' · '+foodNames[food];detail.textContent=(state.memory?.discoveries.includes(food)?'♡ Уже знаємо: це улюблена їжа!':'Який смак оберемо сьогодні?')+'\nОК — погодувати';return;}
 if(mode==='memory'){title.textContent=state.name+' пам’ятає';detail.textContent=memorySummary(state)+(state.memory.lastAdventure?'\nПригода: '+state.memory.lastAdventure.title:'')+(state.heirloom?'\nСпадок: '+state.heirloom.name:'');return;}
 if(mode==='room'){const item=furnishings[choice],owned=state.room?.[item.id];title.textContent=item.name+(owned?' · Є В КІМНАТІ':' · '+item.price+' монет');detail.textContent=item.benefit+'\n'+(owned?'ОК — скористатися':'ОК — придбати');portrait.hidden=false;if(detailedReady()){drawDetailedMain(portrait,state,state.species,0,true,{x:96,feet:128,scale:1},null);}else{const c=portrait.getContext('2d');c.clearRect(0,0,128,100);drawHome(c,state,0);}return;}
 if(mode==='routine'){const [field,name]=routineFields[choice];title.textContent=name;detail.textContent=(field==='enabled'?(state.routine.enabled?'УВІМКНЕНО':'ВИМКНЕНО'):String(state.routine[field]).padStart(2,'0')+':00')+'\nОК — '+(field==='enabled'?'увімкнути / вимкнути':'додати 1 годину')+'\n← → інший пункт · ↶ назад';return;}
 if(mode==='adventure'){const event=adventureOf(state);title.textContent=event?.title||'Зараз спокійно';detail.textContent=event?event.question+'\n▶ '+event.choices[choice].label+'\nОК — відповісти':'Пригоди часом трапляються самі. А поки можна обійнятися.';return;}
 if(mode==='tree'){const row=treeRecords[treeIndex];title.textContent=row?row.name+' · покоління '+row.generation:'Родинне дерево';detail.textContent=row?((row.parents?.length?'Батьки: '+row.parents.map(p=>p.name).join(' + '):'Початок цієї гілки родини')+(row.heirloom?'\nСпадок: '+row.heirloom.name+' від '+row.heirloom.from:'')+'\n'+(treeIndex+1)+'/'+treeRecords.length+' · ← → родичі'):'У нас ще все попереду.';return;}
}
async function companion(command,body={},stay=false){if(busy||!state)return;busy=true;generation++;$('#error').hidden=true;render();try{const r=online?await api('companion',{command,...body}):performCompanion(state,command,body);if(r.error)throw Error(r.error);state=r.state;if(!online)save();if(!['toyTurn','activityStep','cookStep'].includes(command)||!state.playroom?.session&&!state.world?.activity&&!state.cozy?.cooking)speak(r.text);if(r.effect){effect={kind:r.effect,started:Date.now(),until:Date.now()+2000};void audio.react('play',state.species);}if(!stay)mode='normal';}catch(e){fail(e.message);}finally{busy=false;render();}}
async function useRoom(){const item=furnishings[choice];if(!state.room[item.id]){await companion('roomBuy',{item:item.id},true);return;}if(item.id==='bed'){mode='normal';await action('sleep');}else if(item.id==='bowl'){mode='food';choice=0;render();}else if(item.id==='toy'){if(state.vacation||state.sleeping||state.napping||stage(state)==='Яєчко'){speak('Пограємо, коли друг буде вдома й прокинеться.');return;}mode='toys';choice=0;render();}else await companion('roomUse',{item:item.id});}
async function openTree(){if(busy)return;busy=true;treeIndex=0;mode='tree';render();try{treeRecords=online?(await api('tree')).records:lineageRows(state,localAlbum());}catch(e){fail(e.message);}finally{busy=false;render();}}

function idleSpeech(s){const intro=introHint(s);if(intro)return intro;if(s.vacation)return 'Відпочиваю в готелі. Твої обійми заброньовані.';if(s.sleeping||s.napping)return s.world?.dream?'Сниться: '+s.world.dream.title+'…':'Хрр… обійми… хрр…';const story=wakeStory(s);if(story){if(!online)save();return story;}if(s.world?.wakeStoryPending===false&&s.world?.lastDream&&Date.now()-s.world.lastDream.wokeAt<30000)return s.world.lastDream.text;if(s.cozy?.lastRemoved&&Date.now()-s.cozy.lastRemoved.at<120000)return 'Зняв '+(clothes.find(i=>i.id===s.cozy.lastRemoved.id)?.name||'одяг').toLowerCase()+'. Мені незручно. Давай іншу річ?';const urgent=needs(s);if(urgent)return urgent.text;const daily=dailyHint(s);if(daily&&Math.random()<.5)return daily;const ritual=ritualHint(s);if(ritual&&Math.random()<.3)return ritual;const hint=routineHint(s);if(hint)return hint;if(s.adventure)return 'У мене маленька пригода! Заглянь у ◇.';const need=needs(s);if(need)return need.text;if(s.hunger<25)return line('hungry',s.species);if(s.clean<25)return line('dirty',s.species);return Math.random()<.35?traits[traitOf(s)].line:line('idle',s.species);}

function renderWorldChoice(portrait){if(cozyPages.some(([id])=>id===mode)){renderCozyChoice(portrait);return;}if(playroomPages.some(([id])=>id===mode)){renderPlayroomChoice(portrait);return;}if(dailyPages.some(([id])=>id===mode)){renderDailyChoice(portrait);return;}
 const title=$('#choice-title'),detail=$('#choice-detail'),w=state.world||{};portrait.hidden=mode==='world';if(!portrait.hidden){draw(portrait,state.species,Date.now(),state);}
 if(mode==='sandbox'){portrait.hidden=false;drawSandbox(portrait);title.textContent='СПІЛЬНА ПІСОЧНИЦЯ';const other=sandboxPets[Math.floor(choice/4)];detail.textContent=online?(other?other.name+(other.relationship>=3?' ♡':other.relationship<0?' …':'')+' · '+['Привітатись','Пограти разом','Побурчати','Відійти від цього пета'][choice%4]+'\n← → друг і дія · ОК · ↶ додому':'Поки тут тільки ми. Чекаємо інших гравців…'):'Відкрий гру через Telegram, щоб зустріти реальних петів.';return;}if(mode==='stories'){portrait.hidden=false;draw(portrait,state.species,Date.now(),state);title.textContent='НАША МАЛЕНЬКА ІСТОРІЯ';detail.textContent=storyView(state).title+'\n'+storyView(state).steps[Math.min(3,state.living?.story?.step||0)]+'\nОК — подбати / продовжити';return;}if(mode==='world'){title.textContent='МАЛЕНЬКИЙ СВІТ · '+(choice+1)+'/'+worldPages.length;detail.textContent='▶ '+worldPages[choice][1]+'\n← → обрати · ОК зайти';return;}
 if(mode==='ritual'){const labels=ritualOptions(state),count=w.rituals?.[choice]||0;title.textContent=labels[choice];detail.textContent='Разом робили: '+count+(count>=3&&favoriteRitual(state)===choice?' · НАШ УЛЮБЛЕНИЙ ♡':'')+'\nОК — зробити разом · ← → інший ритуал';return;}
 if(mode==='weather'){const weather=weatherAt();title.textContent=weather.name+' за вікном';detail.textContent='Ігрова погода змінюється кожні 3 години.\nДощ — ковдра, сонце — теплі щічки, гроза — схованка.\nЗвук: '+(w.weatherSound!==false?'увімкнено':'вимкнено')+' · ОК перемкнути';return;}
 if(mode==='walk'){const trip=w.walk&&w.walk.expires>Date.now()?w.walk:null;if(trip){const place=walks.find(p=>p.id===trip.place);title.textContent=place.name+' · НА ПРОГУЛЯНЦІ';detail.textContent=place.scene+'\n▶ '+place.choices[choice%2]+'\nОК — обрати';}else{title.textContent=walks[choice%walks.length].name;detail.textContent='Коротка прогулянка разом · −6 енергії\nЗнахідки, видові реакції та +настрій.\n← → місце · ОК вирушити';}return;}
 if(mode==='activity'){const run=w.activity&&w.activity.expires>Date.now()?w.activity:null;const a=activities.find(a=>a.id===run?.kind)||activities[choice%activities.length];title.textContent=(a.id==='groom'?groomName(state):a.name)+(run?' · '+(run.step+1)+'/3':'');detail.textContent=(run?activityStepText(state,a,run.step):a.hint)+'\nЗавершено разом: '+(w.skills?.[a.id]||0)+(a.id==='trick'?' · трюк: '+((w.skills?.trick||0)>=3?'вивчено':'вчимося'):'')+'\nОК — '+(run?'наступний рух':'почати');return;}
 if(mode==='dreams'){title.textContent=w.dream?'ЗАРАЗ СНІТЬСЯ':w.lastDream?'ОСТАННІЙ СОН':'СНИ ДРУГА';detail.textContent=w.dream?w.dream.title:w.lastDream?w.lastDream.title+'\n«'+w.lastDream.text+'»':'Засни хоча б на дві хвилини — і побачиш піксельний сон. Після пробудження друг розповість його.';return;}
 if(mode==='forms'){title.textContent=formNames[careForm(state)];detail.textContent='Вигляд підлітка залежить від догляду. Доросла форма закріплюється при дорослішанні.\nВисокий догляд — блиск і охайність; середній — округлість і сонні очі; низький — чубчик та скуйовджені боки.';}
}
function groomName(s){return {chicken:'Пригладити пір’ячко',frog:'Зволожити спинку',dino:'Почистити луску',dog:'Почистити шерстку'}[s.species]||'Розчесати шерстку';}
async function worldAction(command,body={}){if(busy||!state)return;busy=true;generation++;$('#error').hidden=true;render();try{const r=online?await api('world',{command,...body}):performWorld(state,command,body);if(r.error)throw Error(r.error);state=r.state;if(!online)save();if(!['toyTurn','activityStep','cookStep'].includes(command)||!state.playroom?.session&&!state.world?.activity&&!state.cozy?.cooking)speak(r.text);if(r.effect){effect={kind:r.effect,started:Date.now(),until:Date.now()+3500};void audio.react(r.effect,state.species);}if(command==='walkStart'||command==='activityStart'||command==='walkChoice'||command==='activityStep'&&!state.world.activity)choice=0;}catch(e){fail(e.message);}finally{busy=false;render();}}
async function worldOK(){if(mode==='sandbox'){const pet=sandboxPets[Math.floor(choice/4)];if(pet)await sandboxAction(['hello','play','tease','avoid'][choice%4],pet.id);return;}if(mode==='stories'){await living('story');return;}if(cozyPages.some(([id])=>id===mode)){await cozyOK();return;}if(playroomPages.some(([id])=>id===mode)){await playroomOK();return;}if(dailyPages.some(([id])=>id===mode)){await dailyOK();return;}if(mode==='world'){mode=worldPages[choice][0];choice=0;render();if(mode==='photos')await openMoments();if(mode==='weather'&&state.world.weatherSound!==false)void audio.react(weatherAt().id,state.species);return;}if(mode==='ritual'){await worldAction('ritual',{choice});return;}if(mode==='weather'){await worldAction('weatherSound');if(state.world.weatherSound)void audio.react(weatherAt().id,state.species);return;}if(mode==='walk'){const trip=state.world.walk;if(trip&&trip.expires>Date.now())await worldAction('walkChoice',{eventId:trip.id,choice:choice%2});else await worldAction('walkStart',{place:walks[choice%walks.length].id});return;}if(mode==='activity'){const run=state.world.activity;if(run&&run.expires>Date.now())await worldAction('activityStep',{eventId:run.id});else await worldAction('activityStart',{activity:activities[choice%activities.length].id});return;}mode='world';choice=0;render();}

function dailyCount(){return Math.max(1,mode==='wishes'?3:mode==='photos'?momentRecords.length:mode==='stash'?Object.keys(state.daily?.stash||{}).filter(id=>state.daily.stash[id]>0).length:mode==='mischief'?3:mode==='celebrations'?celebrations(state).length:1);}
function renderDailyChoice(portrait){const d=state.daily||{},title=$('#choice-title'),detail=$('#choice-detail');portrait.hidden=false;
 if(mode==='photos'){const row=momentRecords[choice%Math.max(1,momentRecords.length)];if(!row){portrait.hidden=true;title.textContent='Наш фотоальбом';detail.textContent='Тут з’являться перше купання, трюк, сни, скарби й свята. Моменти зберігаються самі.';return;}const p={...row.pet,portraitStage:row.pet.portraitStage};draw(portrait,p.species,0,p);drawWorld(portrait.getContext('2d'),p,p.portraitStage,{kind:row.kind,started:row.at,until:row.at+1000},row.at,true);drawDaily(portrait.getContext('2d'),p,{kind:row.kind,until:row.at+1000},row.at,true);const frame=portrait.getContext('2d');frame.fillStyle='#e6dfc9';frame.fillRect(0,0,128,2);frame.fillRect(0,98,128,2);frame.fillRect(0,0,2,100);frame.fillRect(126,0,2,100);title.textContent=row.title;detail.textContent=new Intl.DateTimeFormat('uk-UA',{dateStyle:'short',timeStyle:'short'}).format(row.at)+' · '+(choice+1)+'/'+momentRecords.length+'\n«'+row.comment+'»\n← → фото · ОК наступне';return;}
 draw(portrait,state.species,Date.now(),state);
 if(mode==='wishes'){title.textContent='Чого хоче мій друг';detail.textContent=wishText(state)+(d.wish?'\n'+(d.wish.accepted?'Домовились! ':'')+'▶ '+wishAnswers[choice%3]:'')+(d.lastWish?'\nМинуле: '+d.lastWish.result:'');return;}
 if(mode==='stash'){const ids=Object.keys(d.stash||{}).filter(id=>d.stash[id]>0),item=treasures.find(t=>t.id===ids[choice%Math.max(1,ids.length)]);title.textContent=item?item.name+' ×'+d.stash[item.id]:'Поки порожня схованка';detail.textContent=item?'«Це мій скарб. Дуже важливий!»\nОК — покажи мені · ← → інша знахідка':'Пет знаходить дрібниці вдома й на прогулянках. З часом тут буде колекція.';return;}
 if(mode==='mischief'){title.textContent=d.mess?messNames[d.mess.kind]:'Зараз тихо. Підозріло тихо.';detail.textContent=(d.mess?'«Я просто перевіряв, як воно працює!»\n▶ '+messAnswers[choice%3]:'Друг поки нічого не накоїв.')+'\nЗвички: охайність '+(d.habits?.tidy||0)+' · пустощі '+(d.habits?.cheeky||0);return;}
 if(mode==='celebrations'){const events=celebrations(state),event=events[choice%Math.max(1,events.length)];title.textContent=event?.name||'Свята ще попереду';detail.textContent=event?(event.done?'Уже святкували! Фото є в альбомі.':'ОК — тортик, ковпачок і обійми!')+'\n← → інше свято':'Вилуплення, перший тиждень і десята прогулянка — кожен привід святкуємо разом.';return;}
 if(mode==='human'){title.textContent='Твій маленький захисник';detail.textContent=(d.kind?.text||d.lastKind?.text||'Я теж за тобою приглядаю. Поїж, перепочинь і бережи себе, моя людино.')+'\n'+(d.kind?'ОК — дякую, друже':'Немає штрафів, якщо ти зайнятий. Просто знай: я поруч.');}
}
async function openMoments(){busy=true;render();try{momentRecords=online?(await api('moments')).records:[...(state.daily?.photos||[]),...localAlbum().flatMap(r=>r.photos||[])].sort((a,b)=>b.at-a.at);choice=0;}catch(e){fail(e.message);}finally{busy=false;render();}}
async function dailyAction(command,body={}){if(busy)return false;busy=true;generation++;$('#error').hidden=true;render();try{const r=online?await api('daily',{command,...body}):performDaily(state,command,body);if(r.error)throw Error(r.error);state=r.state;if(!online)save();if(!['toyTurn','activityStep','cookStep'].includes(command)||!state.playroom?.session&&!state.world?.activity&&!state.cozy?.cooking)speak(r.text);if(r.effect){effect={kind:r.effect,started:Date.now(),until:Date.now()+4000};void audio.react(['party','treasure'].includes(r.effect)?'gift':r.effect==='human'?'blanket':r.effect==='mischief'?'play':r.effect==='shrug'?'miss':r.effect,state.species);}return true;}catch(e){fail(e.message);return false;}finally{busy=false;render();}}
async function dailyOK(){const d=state.daily;if(mode==='photos'){choice=(choice+1)%Math.max(1,momentRecords.length);render();return;}if(mode==='wishes'){if(!d.wish)return;const wish={...d.wish},answer=choice%3;if(await dailyAction('wishAnswer',{eventId:wish.id,choice:answer})){if(answer===0&&wish.kind==='walk'){mode='walk';choice=Math.max(0,walks.findIndex(p=>p.id===wish.place));render();}else if((answer<2&&wish.kind==='cuddle')||answer===1){mode='ritual';choice=0;render();}}return;}if(mode==='mischief'){if(d.mess)await dailyAction('messAnswer',{eventId:d.mess.id,choice:choice%3});return;}if(mode==='stash'){const id=Object.keys(d.stash||{}).filter(id=>d.stash[id]>0)[choice];if(id)await dailyAction('stashShow',{item:id});return;}if(mode==='celebrations'){const e=celebrations(state)[choice];if(e&&!e.done)await dailyAction('celebrate',{eventId:e.id});return;}if(mode==='human'&&d.kind)await dailyAction('humanAnswer',{eventId:d.kind.id});}

function renderPlayroomChoice(portrait){portrait.hidden=false;draw(portrait,state.species,Date.now(),state);const title=$('#choice-title'),detail=$('#choice-detail'),p=state.playroom;
 if(mode==='toys'){const run=p.session?.expires>Date.now()?p.session:null,toy=toys.find(t=>t.id===run?.kind)||toys[choice%toys.length];title.textContent=toy.name+(run?' · '+run.hits+'/'+(run.kind==='music'?3:5):p.toys[toy.id]?' · НАША':' · '+toy.price+' монет');detail.textContent=toy.hint+'\n'+(run?'↶ — завершити гру без нагороди':p.toys[toy.id]?'ОК — почати · ← → інша іграшка':'ОК — придбати · ← → інша іграшка')+'\nРазом грали: '+(p.skills[toy.id]||0)+((p.skills[toy.id]||0)>=3?' · власний прийом вивчено!':'');return;}
 if(mode==='craft'){const recipe=recipes[choice%recipes.length];title.textContent=recipe.name+(p.crafted[recipe.id]?' · ГОТОВО':'');detail.textContent=Object.entries(recipe.cost).map(([id,n])=>{const item=treasures.find(t=>t.id===id);return item.name+': '+(state.daily.stash[id]||0)+'/'+n;}).join(' · ')+'\n'+recipe.hint+'\nОК — зробити · ← → інший рецепт';return;}
 if(mode==='decorate'){const [field,name]=decorFields[choice%decorFields.length];title.textContent=name;detail.textContent=(field==='layout'?layouts[p.decor.layout]:field==='bedding'?bedding[p.decor.bedding].name:field==='display'?(treasures.find(t=>t.id===p.decor.display)?.name||'Поки без експоната'):favoriteCorner(state).name)+'\n'+(field==='corner'?'Пет сам обрав місце за характером.':'ОК — наступний варіант')+'\n← → інше налаштування';}
}
async function playroomAction(command,body={}){if(busy)return false;busy=true;generation++;$('#error').hidden=true;render();try{const r=online?await api('playroom',{command,...body}):performPlayroom(state,command,body);if(r.error)throw Error(r.error);state=r.state;if(!online)save();if(!['toyTurn','activityStep','cookStep'].includes(command)||!state.playroom?.session&&!state.world?.activity&&!state.cozy?.cooking)speak(r.text);if(r.effect){effect={kind:r.effect,started:Date.now(),until:Date.now()+3000};const sound=r.effect==='music'?'music'+(state.playroom.session?.tune||0):r.effect==='toy'?'pet':r.effect;void audio.react(sound,state.species,(state.playroom.skills.music||0)>=3);}return true;}catch(e){fail(e.message);return false;}finally{busy=false;render();}}
async function toyInput(input){const run=state.playroom.session;if(!run)return;await playroomAction('toyTurn',{eventId:run.id,input});}
async function playroomOK(){const p=state.playroom;if(mode==='toys'){if(p.session?.expires>Date.now()){await toyInput('ok');return;}const toy=toys[choice%toys.length];await playroomAction(p.toys[toy.id]?'toyStart':'toyBuy',{toy:toy.id});return;}if(mode==='craft'){await playroomAction('craft',{recipe:recipes[choice%recipes.length].id});return;}if(mode==='decorate'){const field=decorFields[choice%decorFields.length][0];if(field==='corner'){speak('Сидітиму, де зручно моїм лапкам. '+favoriteCorner(state).name+'.');return;}await playroomAction('decorate',{field});}}

function kitchenOptions(){return (dishes[state.species]||dishes.cat).flatMap(d=>additionsFor(state).map(addition=>({dish:d,addition})));}
function cozyCount(){if(mode==='shop')return homeGoods.length;if(mode==='wardrobe')return clothes.length;if(mode==='belongings')return Math.max(1,ownedThings(state).length*4);if(mode==='hide')return state.cozy.hide?.expires>Date.now()?hideSpots(state).length:1;if(mode==='kitchen')return state.cozy.cooking?.expires>Date.now()?1:kitchenOptions().length+1;if(mode==='peace')return 4;return 1;}
function renderCozyChoice(portrait){const c=state.cozy,title=$('#choice-title'),detail=$('#choice-detail');portrait.hidden=false;draw(portrait,state.species,Date.now(),state);
 if(mode==='shop'){const item=homeGoods[choice%homeGoods.length];title.textContent=item.name+(c.owned[item.id]?' · ВДОМА':' · '+item.price+' монет');detail.textContent=c.owned[item.id]?'Власна річ із характером. ОК — скористатися.':'ОК — придбати · ← → інші предмети';return;}
 if(mode==='wardrobe'){const item=clothes[choice%clothes.length],owned=c.outfits[item.id],worn=c.wearing[item.slot]===item.id;title.textContent=item.name+(worn?' · НА МЕНІ':owned?' · У ГАРДЕРОБІ':' · '+item.price+' монет');detail.textContent=(itemStatus(state,item.id).known?opinionNames[opinion(state,item.id)]:'Спочатку приміряємо — тоді дізнаємося вподобання.')+'\n'+(owned?'ОК — '+(worn?'зняти':'вдягнути'):'ОК — придбати')+'\nНезручний одяг можу зняти сам. Ремонт — у «Мої речі».';return;}
 if(mode==='belongings'){const items=ownedThings(state),item=items[Math.floor(choice/4)%Math.max(1,items.length)];title.textContent=item?.name||'Речі ще попереду';if(!item){detail.textContent='Зазирни в крамничку або придбай іграшку.';return;}const status=itemStatus(state,item.id);detail.textContent=(status.known?opinionNames[opinion(state,item.id)]:'Ще знайомимося')+' · стан '+status.wear+'%\n▶ '+(objectActions(item.id)[choice%4][1]+(choice%4===3?' · 2 монети':''))+(item.id==='bed'?'\nСон: +'+bedBonus(state).toFixed(1)+' енергії/год · '+variants[state.living?.furniture?.bed||0].name:'')+'\n← → речі й дії · ОК';return;}
 if(mode==='hide'){const run=c.hide?.expires>Date.now()?c.hide:null;title.textContent=run?'ДЕ СХОВАВСЯ ДРУГ?':'ПОГРАЄМО В ХОВАНКИ?';detail.textContent=run?'Шукай, де щось стирчить.\n▶ '+hideSpots(state)[choice%hideSpots(state).length].name+'\nОК — перевірити':'Пет сховається за предметом у великій кімнаті.\nОК — почати · ← → обрати місце пошуку';if(run&&detailedReady()){drawDetailedMain(portrait,state,state.species,Date.now(),reduced,null,effect);}else if(run){portrait.width=192;portrait.height=144;const ctx=portrait.getContext('2d');ctx.clearRect(0,0,192,144);drawExpandedRoom(ctx,state,Date.now(),reduced);drawHideClue(ctx,state);}return;}
 if(mode==='kitchen'){if(c.cooking?.expires>Date.now()){title.textContent='ГОТУЄМО РАЗОМ · '+(c.cooking.step+1)+'/3';detail.textContent='Змішати → приготувати → скуштувати.\nОК — наступний крок';return;}const options=kitchenOptions(),option=options[choice];if(!option){title.textContent='Поповнити комору · 3 монети';detail.textContent='По 2 порції кожного продукту.\n'+ingredients.map(i=>i.name+': '+(c.pantry[i.id]||0)).join(' · ')+'\nОК — купити';return;}const key=option.dish.id+'-'+option.addition;title.textContent=option.dish.name;detail.textContent='Добавка: '+({plain:'без добавки',berry:'ягідки',greens:state.species==='frog'?'водорості':'зелень'}[option.addition])+'\nПродукти: '+ingredients.find(i=>i.id===option.dish.base).name+' ×1'+(option.addition!=='plain'?' + '+ingredients.find(i=>i.id===option.addition).name+' ×1':'')+(c.foodMemory[key]?'\n'+(isFavoriteMeal(state,option.dish.id,option.addition)?'♡ Улюблене поєднання!':'Уже куштували. Оцінка: смачно.'):'')+'\nОК — готувати · ← → рецепт';return;}
 if(mode==='peace'){title.textContent='МИР І ОБІЙМИ';detail.textContent='Образа: '+c.peace.tension+'/5 · з часом минає.\n▶ '+['Запропонувати обійми','Запропонувати гру','Тихо посидіти поруч','Мені це не подобається'][choice%4]+'\nОК — сказати';return;}
 if(mode==='night'){title.textContent='НІЧНЕ ЖИТТЯ КІМНАТИ';detail.textContent=(c.nightMode?'Увімкнено':'Вимкнено')+' · '+(isNight(state)?'Зараз ніч':'Зараз день')+'\nУночі — тихе світло, світлячки, сонне ворушіння й короткий похід по воду.\nОК — перемкнути · часовий пояс '+state.routine.timezone;}
}
async function cozyAction(command,body={}){if(busy)return false;busy=true;generation++;$('#error').hidden=true;render();try{const r=online?await api('cozy',{command,...body}):performCozy(state,command,body);if(r.error)throw Error(r.error);state=r.state;if(!online)save();if(!['toyTurn','activityStep','cookStep'].includes(command)||!state.playroom?.session&&!state.world?.activity&&!state.cozy?.cooking)speak(r.text);if(r.effect){effect={kind:r.effect,started:Date.now(),until:Date.now()+3200};void audio.react({cook:'cook',hide:'play',shrug:'miss',toy:'pet'}[r.effect]||r.effect,state.species);}return true;}catch(e){fail(e.message);return false;}finally{busy=false;render();}}
async function cozyOK(){const c=state.cozy;if(mode==='shop'){const item=homeGoods[choice%homeGoods.length];await cozyAction(c.owned[item.id]?'itemUse':'shopBuy',{item:item.id});return;}if(mode==='wardrobe'){const item=clothes[choice%clothes.length];await cozyAction(c.outfits[item.id]?'clothesWear':'clothesBuy',{item:item.id});return;}if(mode==='belongings'){const item=ownedThings(state)[Math.floor(choice/4)];if(item){const command=objectActions(item.id)[choice%4][0];if(command==='putOn'){await cozyAction('clothesWear',{item:item.id});return;}if(['use','gentle','jump','rest','replace','repair'].includes(command))await living(command,{item:item.id});}return;}if(mode==='hide'){if(c.hide?.expires>Date.now())await cozyAction('hideGuess',{eventId:c.hide.id,spot:hideSpots(state)[choice%hideSpots(state).length].id});else await cozyAction('hideStart');return;}if(mode==='kitchen'){if(c.cooking?.expires>Date.now())await cozyAction('cookStep',{eventId:c.cooking.id});else{const option=kitchenOptions()[choice];if(option)await cozyAction('cookStart',{dish:option.dish.id,addition:option.addition});else await cozyAction('pantryBuy');}return;}if(mode==='peace'){const response=['hug','play','sit','boundary'][choice%4];const ok=await cozyAction('peace',{response});if(ok&&response==='play'){mode='toys';choice=0;render();}return;}if(mode==='night')await cozyAction('nightToggle');}

async function living(command,body={}){if(busy)return;busy=true;try{const r=online?await api('living',{command,...body}):livingAction(state,command,body);if(r.error)throw Error(r.error);state=r.state;if(!online)save();speak(r.text);if(r.effect){effect={kind:r.effect,started:Date.now(),until:Date.now()+3500};void audio.react(r.effect,state.species);}}catch(e){fail(e.message);}finally{busy=false;render();}}
async function sandboxAction(command,target){if(!online||busy)return;busy=true;try{const r=await api('sandbox',{command,target});if(mode!=='sandbox')return;state=r.state;sandboxPets=r.pets||[];choice%=Math.max(1,sandboxPets.length*4);if(r.text)speak(r.text);if(!sandboxTimer)sandboxTimer=setInterval(()=>{if(mode==='sandbox'&&!busy&&!document.hidden)void sandboxAction('poll');},8000);}catch(e){fail(e.message);}finally{busy=false;render();}}
function drawSandbox(cv){if(detailedReady()){drawDetailedSandbox(cv,state,sandboxPets,Math.floor(choice/4),Date.now(),reduced);return;}cv.width=192;cv.height=144;const c=cv.getContext('2d');c.imageSmoothingEnabled=false;c.fillStyle='#bfcba3';c.fillRect(0,0,192,144);c.fillStyle='#cfbd8e';c.fillRect(6,48,180,91);c.fillStyle='#8d7755';c.fillRect(4,139,184,4);const selected=Math.floor(choice/4),page=Math.floor(selected/8),visitors=sandboxPets.slice(page*8,page*8+8),peers=[{species:state.species,name:state.name,own:true},...visitors];for(const [i,p]of peers.entries()){const layer=document.createElement('canvas');layer.width=128;layer.height=100;drawClassic(layer,p.species,Date.now(),{...(i===0?state:p.look),species:p.species,born:state.born,id:p.id||state.id,sleeping:false,napping:false,dead:false,world:{},cozy:i===0?state.cozy:p.look?.cozy||{wearing:{}}},false,true);const x=i===0?96:24+(i-1)%4*48,y=i===0?138:79+Math.floor((i-1)/4)*31;c.drawImage(layer,31,8,68,80,x-16,y-38,32,38);if(i>0&&selected===page*8+i-1){c.fillStyle='#526846';c.fillRect(x-3,y-43,6,3);}}}


function smoothPose(target,frame,s){if(!smoothScene||smoothScene.id!==s?.id||reduced){smoothScene={...target,id:s?.id,t:frame};return target;}const k=Math.min(1,Math.max(0,(frame-smoothScene.t)/700));for(const key of ['x','feet','scale'])smoothScene[key]+=(target[key]-smoothScene[key])*k;smoothScene.t=frame;return {...target,x:smoothScene.x,feet:smoothScene.feet,scale:smoothScene.scale};}

function renderInteractionControls(){const wrapper=$('#sandbox-controls');wrapper.hidden=mode!=='sandbox';if(mode!=='sandbox')return;const peers=$('#sandbox-peers'),actions=$('#sandbox-actions');peers.replaceChildren();actions.replaceChildren();sandboxPets.forEach((pet,i)=>{const button=document.createElement('button');button.type='button';button.className='sandbox-peer'+(Math.floor(choice/4)===i?' selected':'');button.textContent=pet.name;button.disabled=busy;button.setAttribute('aria-pressed',String(Math.floor(choice/4)===i));button.onclick=()=>{if(busy)return;choice=i*4;render();};peers.append(button);});const selected=sandboxPets[Math.floor(choice/4)];for(const [i,[command,label]]of [['hello','Привітатись'],['play','Грати'],['tease','Побурчати'],['avoid','Відійти']].entries()){const button=document.createElement('button');button.type='button';button.className='sandbox-action'+(choice%4===i?' selected':'');button.setAttribute('aria-label',label+(selected?' · '+selected.name:''));button.disabled=busy||!online||!selected;const text=document.createElement('span');text.textContent=label;button.append(actionIcon(command),text);button.onclick=()=>{if(busy||!selected)return;choice=Math.floor(choice/4)*4+i;void audio.unlock();void sandboxAction(command,selected.id);};actions.append(button);}}

void loadDetailedAssets().then(ok=>{if(!ok){if(typeof Image!=='undefined')fail('Не вдалося завантажити зображення. Перевідкрий гру, будь ласка.');return;}document.querySelectorAll('.species-card canvas').forEach((canvas,i)=>draw(canvas,species[i].id,1000,null,true));render();});
